const { writeFileSync, mkdirSync } = await import('node:fs');
const { join } = await import('node:path');
const os = await import('node:os');
const input = globalThis.input;
if (!input || typeof input.url !== 'string') { throw new Error('Missing required input: url'); }
const outPath = input.output_path || join(os.tmpdir(), `geektopdf-${Date.now()}.pdf`);
const dir = join(outPath, '..');
try { mkdirSync(dir, { recursive: true }); } catch (_) {}
globalThis.outputPath = outPath;

const mod = await import('geek-time-topdf');
const fn = mod.default || mod;
await fn({ url: globalThis.input.url, outputPath: globalThis.outputPath });
globalThis.result = { pdf_path: globalThis.outputPath };
